// Agite frenético: nunca se queda quieto; en el anillo baila (flanquea) y a veces se reacomoda.
let step, plan = null;
if (range < combatRange.min) {
  step = nextRetreatStep(actor, target, combatRange.min, combatRange.max); plan = 'retreat';
